    static FamilyFormTable* GetFamilyFormTable(Scene& scene)
    {
        if (scene.mEntityTables.find("Vim.FamilyForm") == scene.mEntityTables.end())
            return {};
        
        return new FamilyFormTable(scene.mEntityTables["Vim.FamilyForm"], scene.mStrings);
    }
    
