            int* newData = new int[count];
            if (mEntityTable.column_exists("int:New")) {
                memcpy(newData, mEntityTable.mDataColumns["int:New"].begin(), count * sizeof(int));
            }
            
            std::vector<int>* result = new std::vector<int>(newData, newData + count);
            
